"use strict";
try{document.body.classList.toggle("comm-large",localStorage.getItem("rebirth_large_type")==="on")}catch{}
(()=>{
 const login=document.querySelector('#login-form'),register=document.querySelector('#register-form'),logout=document.querySelector('#logout-form'),error=document.querySelector('#auth-error');
 async function submit(path,body,button){button.disabled=true;error.hidden=true;try{const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json',...(globalThis.accountId?{'X-Rebirth-Account':globalThis.accountId}:{})},body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(data.error||'暂时没能完成，请再试一次');location.assign(path==='/api/login'||path==='/api/register'?'/workbench':'/login')}catch(e){error.textContent=e.message;error.hidden=false;error.focus()}finally{button.disabled=false}}
 login?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(login);submit('/api/login',{username:String(f.get('username')),password:String(f.get('password'))},login.querySelector('[type=submit]'))});
 register?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(register);if(f.get('password')!==f.get('password_confirm')){error.textContent='两次密码不一致，请重新确认。';error.hidden=false;error.focus();return}submit('/api/register',{username:String(f.get('username')),password:String(f.get('password')),password_confirm:String(f.get('password_confirm')),test_consent:f.has('test_consent')},register.querySelector('[type=submit]'))});
 if(register||login)fetch('/api/public-settings',{cache:'no-store'}).then(async r=>{if(!r.ok)throw Error();const settings=await r.json();const entry=document.querySelector('#register-link');if(entry)entry.hidden=!settings.registration_open;const message=document.querySelector('#registration-message');if(message)message.textContent=settings.registration_open?'第一次来？注册一个账号，开始记录自己的小店。':'暂未开放自行注册。没有账号或忘记密码，请联系管理员。';if(register){document.querySelector('#registration-state').textContent=settings.registration_open?(settings.setup_required?'首次使用：请建立管理员账号。以后可在“账号 → 管理账号”管理成员。':'填好下面三项，注册后会自动打开你的工作台。'):'暂未开放注册，请联系管理员。';register.querySelector('[type=submit]').disabled=!settings.registration_open;document.querySelector('#demo-consent').hidden=!settings.demo_only;register.elements.test_consent.required=!!settings.demo_only}}).catch(()=>{if(register)document.querySelector('#registration-state').textContent='暂时读不到注册状态，请稍后刷新；尚未创建账号。'});
 document.querySelector('#password-visibility')?.addEventListener('click',e=>{const field=login.elements.password,visible=field.type==='password';field.type=visible?'text':'password';e.target.textContent=visible?'隐藏密码':'显示密码';e.target.setAttribute('aria-pressed',String(visible))});
 logout?.addEventListener('submit',e=>{e.preventDefault();submit('/api/logout',{},logout.querySelector('[type=submit]'))});
 if(logout)fetch('/api/session',{cache:'no-store'}).then(async r=>{if(!r.ok){location.assign('/login');return}const data=await r.json();if(!document.querySelector('#edit-profile'))document.querySelector('#account-name').textContent=data.user.name;const role=document.querySelector('#account-role');if(role)role.textContent=data.user.role==='admin'?'管理员账号':'经营者账号';const admin=document.querySelector('#admin-link');if(admin)admin.hidden=data.user.role!=='admin';globalThis.accountId=data.user.id}).catch(()=>{document.querySelector('#account-name').textContent='暂时读不到账号，请保持联网后刷新。'});
 const security=document.querySelector('#security-panel'),securityButton=document.querySelector('#open-security');
 securityButton?.addEventListener('click',()=>{security.hidden=!security.hidden;securityButton.setAttribute('aria-expanded',String(!security.hidden));if(!security.hidden)security.querySelector('input').focus()});
 document.querySelector('#cancel-security')?.addEventListener('click',()=>{security.hidden=true;security.querySelector('form').reset();securityButton.setAttribute('aria-expanded','false');securityButton.focus()});
 document.querySelector('#open-signout')?.addEventListener('click',()=>{document.querySelector('#signout-panel').hidden=false});
 document.querySelector('#cancel-signout')?.addEventListener('click',()=>{document.querySelector('#signout-panel').hidden=true;document.querySelector('#open-signout').focus()});
 const large=document.querySelector('#large-type-setting');function syncLarge(){large?.setAttribute('aria-pressed',String(document.body.classList.contains('comm-large')))}syncLarge();
 large?.addEventListener('click',()=>{const on=!document.body.classList.contains('comm-large');document.body.classList.toggle('comm-large',on);try{localStorage.setItem('rebirth_large_type',on?'on':'off')}catch{}syncLarge()});
 document.querySelector('#password-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget,f=new FormData(form);submit('/api/account/password',Object.fromEntries(f),form.querySelector('[type=submit]'))});
})();
